UPGRADE_SQL = "SET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_advance_contact_revision(p_user uuid, p_approval uuid)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$\nDECLARE\n    approved_email text;\nBEGIN\n    SELECT requested_email_normalized INTO approved_email\n    FROM user_contact_approvals\n    WHERE approval_id = p_approval AND user_id = p_user\n      AND request_type = 'change' AND status = 'approved' AND expires_at > clock_timestamp();\n    IF approved_email IS NULL THEN\n        RAISE EXCEPTION 'contact change requires an approved, unexpired change approval'\n            USING ERRCODE = 'check_violation';\n    END IF;\n    UPDATE users\n    SET normalized_email = approved_email,\n        contact_revision = contact_revision + 1\n    WHERE user_id = p_user;\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_approve_change_with_proof(\n    p_proof uuid, p_approval uuid, p_proof_ref text, p_sealed_old_contact bytea,\n    p_old_contact_ref text)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    actor uuid;\n    target uuid;\n    requester uuid;\n    old_email text;\nBEGIN\n    actor := webdesk_guard.fn_consume_operation_proof(p_proof, 'contact.approve.change', p_approval);\n    PERFORM 1 FROM user_contact_approvals a\n    WHERE a.approval_id = p_approval AND a.status = 'pending' AND a.expires_at > clock_timestamp()\n    FOR UPDATE OF a;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'approval_not_pending' USING ERRCODE = 'check_violation';\n    END IF;\n    SELECT user_id, requested_by_user_id INTO target, requester\n    FROM user_contact_approvals WHERE approval_id = p_approval;\n    IF requester = actor THEN\n        RAISE EXCEPTION 'self_approval' USING ERRCODE = 'check_violation';\n    END IF;\n    SELECT normalized_email INTO old_email FROM users WHERE user_id = target;\n    UPDATE user_contact_approvals\n    SET status = 'approved', approved_by_user_id = actor, proof_ref = p_proof_ref,\n        approved_at = now(), revision = revision + 1\n    WHERE approval_id = p_approval;\n    PERFORM webdesk_guard.fn_advance_contact_revision(target, p_approval);\n    UPDATE users SET revision = revision + 1 WHERE user_id = target;\n    PERFORM webdesk_guard.fn_release_reservations(target, 'contact_change', p_approval, old_email);\n    PERFORM webdesk_guard.fn_revoke_tokens(target, 'contact_change');\n    PERFORM webdesk_guard.fn_revoke_user_sessions(target, p_approval);\n    INSERT INTO outbox_notices (purpose, user_id, old_contact_ref, old_contact_ciphertext,\n                                payload_redacted, status)\n    VALUES ('prior_contact_change', target, p_old_contact_ref, p_sealed_old_contact,\n            '{}'::jsonb, 'queued');\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_approve_create_with_proof(\n    p_proof uuid, p_approval uuid, p_proof_ref text)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    actor uuid;\n    target uuid;\n    requester uuid;\nBEGIN\n    actor := webdesk_guard.fn_consume_operation_proof(p_proof, 'contact.approve.create', p_approval);\n    PERFORM 1 FROM user_contact_approvals a\n    WHERE a.approval_id = p_approval AND a.status = 'pending' AND a.expires_at > clock_timestamp()\n    FOR UPDATE OF a;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'approval_not_pending' USING ERRCODE = 'check_violation';\n    END IF;\n    SELECT user_id, requested_by_user_id INTO target, requester\n    FROM user_contact_approvals WHERE approval_id = p_approval;\n    IF requester = actor THEN\n        RAISE EXCEPTION 'self_approval' USING ERRCODE = 'check_violation';\n    END IF;\n    UPDATE user_contact_approvals\n    SET status = 'approved', approved_by_user_id = actor, proof_ref = p_proof_ref,\n        approved_at = now(), revision = revision + 1\n    WHERE approval_id = p_approval;\n    UPDATE users SET status = 'pending_activation', revision = revision + 1 WHERE user_id = target;\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_cancel_change_with_proof(p_proof uuid, p_approval uuid)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    actor uuid;\nBEGIN\n    actor := webdesk_guard.fn_consume_operation_proof(p_proof, 'contact.cancel.change', p_approval);\n    PERFORM 1 FROM user_contact_approvals a\n    WHERE a.approval_id = p_approval AND a.status = 'pending' AND a.expires_at > clock_timestamp()\n    FOR UPDATE OF a;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'approval_not_pending' USING ERRCODE = 'check_violation';\n    END IF;\n    UPDATE user_contact_approvals SET status = 'cancelled' WHERE approval_id = p_approval;\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_issue_ceremony_activation(\n    p_user uuid, p_token_hash text, p_destination text, p_ttl_seconds integer)\nRETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM user_contact_approvals a\n        WHERE a.user_id = p_user AND a.administrator_appointment AND a.ceremony_id IS NOT NULL\n          AND a.status = 'approved' AND a.expires_at > clock_timestamp()) THEN\n        RAISE EXCEPTION 'ceremony activation needs a live ceremony-backed appointment'\n            USING ERRCODE = 'check_violation';\n    END IF;\n    RETURN webdesk_guard.fn_issue_token(\n        p_user, 'activate', p_token_hash, p_destination, p_ttl_seconds, NULL);\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_issue_owner_reset_token(\n    p_user uuid, p_token_hash text, p_destination text, p_ttl_seconds integer)\nRETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    pending_change boolean;\nBEGIN\n    SELECT EXISTS (\n        SELECT 1 FROM user_contact_approvals a\n        WHERE a.user_id = p_user AND a.request_type = 'change' AND a.status = 'pending'\n          AND a.expires_at > clock_timestamp()\n    ) INTO pending_change;\n    IF pending_change THEN\n        RAISE EXCEPTION 'reset is refused while a contact change is pending'\n            USING ERRCODE = 'check_violation';\n    END IF;\n    RETURN webdesk_guard.fn_issue_token(p_user, 'reset', p_token_hash, p_destination,\n                                        p_ttl_seconds, NULL);\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_issue_token(\n    p_user uuid, p_purpose text, p_token_hash text, p_destination text,\n    p_ttl_seconds integer, p_actor uuid)\nRETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$\nDECLARE\n    user_status text;\n    user_email text;\n    user_revision integer;\n    new_token uuid;\nBEGIN\n    IF p_purpose NOT IN ('activate', 'reset') THEN\n        RAISE EXCEPTION 'invalid token purpose' USING ERRCODE = 'check_violation';\n    END IF;\n    SELECT status, normalized_email, contact_revision\n    INTO user_status, user_email, user_revision\n    FROM users WHERE user_id = p_user FOR UPDATE;\n    IF NOT FOUND OR user_email IS NULL THEN\n        RAISE EXCEPTION 'token issuance is not eligible' USING ERRCODE = 'check_violation';\n    END IF;\n    IF p_purpose = 'activate' THEN\n        IF user_status <> 'pending_activation' OR NOT EXISTS (\n            SELECT 1 FROM user_contact_approvals a\n            WHERE a.user_id = p_user AND a.status = 'approved'\n              AND a.requested_email_normalized = user_email AND a.expires_at > clock_timestamp()\n        ) THEN\n            RAISE EXCEPTION 'activation token needs a live approved contact approval'\n                USING ERRCODE = 'check_violation';\n        END IF;\n    ELSIF user_status <> 'active' THEN\n        RAISE EXCEPTION 'reset token needs an active account'\n            USING ERRCODE = 'check_violation';\n    END IF;\n    UPDATE account_activation_tokens\n    SET revoked_at = now(), revocation_reason = 'superseded'\n    WHERE user_id = p_user AND purpose = p_purpose AND consumed_at IS NULL AND revoked_at IS NULL;\n    INSERT INTO account_activation_tokens (user_id, purpose, token_hash, contact_revision,\n        contact_destination_ref, expires_at, delivery_status, issued_by_actor_id)\n    VALUES (p_user, p_purpose, p_token_hash, user_revision, p_destination,\n        now() + make_interval(secs => p_ttl_seconds), 'pending', p_actor)\n    RETURNING token_id INTO new_token;\n    RETURN new_token;\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_reject_create_with_proof(p_proof uuid, p_approval uuid)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    actor uuid;\nBEGIN\n    actor := webdesk_guard.fn_consume_operation_proof(p_proof, 'contact.reject.create', p_approval);\n    PERFORM 1 FROM user_contact_approvals a\n    WHERE a.approval_id = p_approval AND a.status = 'pending' AND a.expires_at > clock_timestamp()\n    FOR UPDATE OF a;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'approval_not_pending' USING ERRCODE = 'check_violation';\n    END IF;\n    UPDATE user_contact_approvals SET status = 'rejected'\n    WHERE approval_id = p_approval AND status = 'pending';\nEND\n$fn$;\nRESET ROLE;\n\nSET ROLE webdesk_guard_owner;\nCREATE OR REPLACE FUNCTION webdesk_guard.fn_revoke_expired_activation_tokens()\nRETURNS TABLE(token_id uuid, user_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$\nBEGIN\n    RETURN QUERY\n    UPDATE account_activation_tokens t\n    SET revoked_at = now(), revocation_reason = 'approval_expired'\n    FROM users u\n    WHERE u.user_id = t.user_id AND u.status = 'pending_activation'\n      AND t.consumed_at IS NULL AND t.revoked_at IS NULL\n      AND NOT EXISTS (\n          SELECT 1 FROM user_contact_approvals a\n          WHERE a.user_id = u.user_id AND a.status = 'approved' AND a.expires_at > clock_timestamp()\n            AND a.requested_email_normalized = u.normalized_email)\n    RETURNING t.token_id, t.user_id;\nEND\n$fn$;\nRESET ROLE;\n"

